code.cpp:
class Solution {
public:
    bool possibleToStamp(vector<vector<int>>& grid, int stampHeight, int stampWidth) {
        int m = grid.size(), n = grid[0].size();
        int h = stampHeight, w = stampWidth;
        vector<vector<int>> P(m + 1, vector<int>(n + 1, 0));
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++)
                P[i + 1][j + 1] = P[i][j + 1] + P[i + 1][j] - P[i][j] + grid[i][j];
        vector<vector<int>> F(m + 1, vector<int>(n + 1, 0));
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j]) continue;
                if (i >= h - 1 && j >= w - 1) {
                    int a = i - h + 1, b = j - w + 1;
                    int cnt = P[i + 1][j + 1] - P[a][j + 1] - P[i + 1][b] + P[a][b];
                    if (cnt == 0) F[i + 1][j + 1] = 1;
                }
            }
        }
        for (int i = 0; i <= m; i++)
            for (int j = 0; j < n; j++)
                F[i][j + 1] += F[i][j];
        for (int i = 0; i < m; i++)
            for (int j = 0; j <= n; j++)
                F[i + 1][j] += F[i][j];
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j]) continue;
                int r2 = min(m, i + h), c2 = min(n, j + w);
                int c = F[r2][c2] - F[i][c2] - F[r2][j] + F[i][j];
                if (c == 0) return false;
            }
        }
        return true;
    }
};
